PRAGMA foreign_keys=OFF;
BEGIN TRANSACTION;
CREATE TABLE access_requests(request_id TEXT PRIMARY KEY, employee_id TEXT NOT NULL REFERENCES employees(employee_id), resource_name TEXT NOT NULL, business_reason TEXT NOT NULL, request_state TEXT NOT NULL, requested_on TEXT NOT NULL, reviewed_by TEXT REFERENCES employees(employee_id), review_note TEXT, access_group TEXT NOT NULL REFERENCES support_groups(group_id));
CREATE TABLE assets(asset_id TEXT PRIMARY KEY, asset_name TEXT, owner_team TEXT, environment TEXT, status TEXT);
CREATE TABLE employee_skills(employee_id TEXT NOT NULL REFERENCES employees(employee_id), skill_name TEXT NOT NULL, proficiency TEXT NOT NULL, years_experience INTEGER NOT NULL, PRIMARY KEY(employee_id,skill_name));
CREATE TABLE employees(employee_id TEXT PRIMARY KEY, full_name TEXT, team TEXT, job_title TEXT, skills TEXT, email TEXT, active INTEGER);
CREATE TABLE knowledge_articles(article_id TEXT PRIMARY KEY, article_title TEXT NOT NULL, problem TEXT NOT NULL, procedure TEXT NOT NULL, owner_employee TEXT NOT NULL REFERENCES employees(employee_id), asset_ref TEXT NOT NULL REFERENCES assets(asset_id), revision INTEGER NOT NULL, last_modified TEXT NOT NULL, access_group TEXT NOT NULL REFERENCES support_groups(group_id));
CREATE TABLE maintenance_history(work_order_id TEXT PRIMARY KEY, asset_ref TEXT NOT NULL REFERENCES assets(asset_id), technician_id TEXT NOT NULL REFERENCES employees(employee_id), fault_summary TEXT NOT NULL, action_taken TEXT, work_status TEXT NOT NULL, opened_on TEXT NOT NULL, completed_on TEXT, downtime_minutes INTEGER, access_group TEXT NOT NULL REFERENCES support_groups(group_id));
CREATE TABLE support_groups(group_id TEXT PRIMARY KEY, group_name TEXT);
CREATE INDEX ix_maintenance_asset ON maintenance_history(asset_ref);
CREATE INDEX ix_access_employee ON access_requests(employee_id);
COMMIT;
PRAGMA foreign_keys=ON;
