INSERT INTO "knowledge_articles" VALUES('KB0001','VPN DNS lookup failure troubleshooting','VPN DNS lookup failure','Validate resolver reachability, compare approved DNS settings and restart the client.','EMP001','AST001',1,'2026-06-01','NETOPS');
